describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        /at least one policy/,
      );
    });

    it("accepts single policy", () => {
      expect(
        () => new CompositeDiscountPolicy([new NoDiscountPolicy()]),
      ).not.toThrow();
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 1000
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("each child receives original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 5000
          new PercentageDiscountPolicy(50), // 5000
        ],
        "sum",
      );
      // Both get 10000 as input, sum = 10000
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 10000 = 5000, remaining = 5000
          new PercentageDiscountPolicy(50), // 50% of 5000 = 2500, remaining = 2500
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(7500);
    });

    it("order matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // 1000 off 10000, rem=9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900
        ],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, rem=9000
          new FixedAmountDiscountPolicy(1000), // 1000 off 9000
        ],
        "chain",
      );
      expect(composite1.computeDiscountCents(10000)).toBe(1900);
      expect(composite2.computeDiscountCents(10000)).toBe(2000);
    });

    it("caps each step at remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(8000), // takes 8000, remaining = 2000
          new FixedAmountDiscountPolicy(5000), // capped at 2000
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(20)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

