describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        /at least one weight bracket/,
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 200 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 200 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for zero-weight cart", () => {
      const lines = [makeLine("a", 100, 2)]; // no weightGrams
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const lines = [makeLine("a", 100, 1, 400)];
      expect(calc.computeShippingCents(lines, 100)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const lines = [makeLine("a", 100, 1, 500)];
      expect(calc.computeShippingCents(lines, 100)).toBe(300);
    });

    it("selects next bracket when weight exceeds previous", () => {
      const lines = [makeLine("a", 100, 1, 501)];
      expect(calc.computeShippingCents(lines, 100)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      const lines = [makeLine("a", 100, 1, 5000)];
      expect(calc.computeShippingCents(lines, 100)).toBe(1200);
    });

    it("uses overflow (last bracket cost) when weight exceeds all brackets", () => {
      const lines = [makeLine("a", 100, 1, 6000)];
      expect(calc.computeShippingCents(lines, 100)).toBe(1200);
    });

    it("uses explicit overflowCostCents when set", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 100, 1, 6000)];
      expect(calcWithOverflow.computeShippingCents(lines, 100)).toBe(2000);
    });

    it("sums weight across multiple lines", () => {
      const lines = [
        makeLine("a", 100, 2, 300), // 600g
        makeLine("b", 200, 1, 200), // 200g
      ];
      // total = 800g → bracket 1000g = 600 cents
      expect(calc.computeShippingCents(lines, 500)).toBe(600);
    });

    it("sorts brackets by upToGrams regardless of input order", () => {
      const unsortedCalc = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      const lines = [makeLine("a", 100, 1, 400)];
      expect(unsortedCalc.computeShippingCents(lines, 100)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product again", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("adds different products separately", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      expect(cart.itemCount).toBe(3);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes a product and returns true", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of an existing product", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 1)).toThrow(
        /not in the cart/,
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);
    });

    it("mutations to snapshot do not affect cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals — pricing pipeline", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2500
      const t = cart.totals();
      expect(t.subtotalCents).toBe(4500);
    });

    it("applies discount policy", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(productA, 1); // subtotal = 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(500);
      expect(discount.computeDiscountCents).toHaveBeenCalledWith(1000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 9999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(productA, 1); // subtotal = 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: () => -100,
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(productA, 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(50),
      };
      const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
      cart.add(productA, 1); // subtotal = 1000, discount = 500, discounted = 500
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(500, "US");
    });

    it("uses configured region for tax", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(productA, 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("computes shipping on lines and discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(799),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(productA, 1); // subtotal=1000, discounted=800
      cart.totals();
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
      const tax: TaxCalculator = { computeTaxCents: () => 80 };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(productA, 1); // subtotal=1000, discount=200, discounted=800
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1000);
      expect(t.discountCents).toBe(200);
      expect(t.taxCents).toBe(80);
      expect(t.shippingCents).toBe(500);
      expect(t.totalCents).toBe(800 + 80 + 500); // 1380
    });

    it("empty cart has all zeros", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = { computeTaxCents: () => -100 };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: () => -50,
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { InventoryError, refreshPrices } from "../src/inventory.ts";
import type { PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("has correct shape and properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("supports undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "b", name: "B", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("refreshes prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation((id: string) => {
        if (id === "a") return Promise.resolve(150);
        return Promise.resolve(250);
      }),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[1]!.product.unitPriceCents).toBe(250);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves product properties other than price", async () => {
    const line: CartLine[] = [
      {
        product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 500, currency: "EUR" },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };
    const result = await refreshPrices(line, fetcher);
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.name).toBe("X");
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network fail")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("network fail");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
      expect(result.totals.subtotalCents).toBe(1500);
    });

    it("uses original prices when no fetcher provided", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("propagates fetcher errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("timeout")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "timeout",
      );
    });
  });

  describe("inventory check", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      await expect(cart.checkout({ inventoryChecker: checker })).rejects.toThrow(
        InventoryError,
      );
      try {
        await cart.checkout({ inventoryChecker: checker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      await expect(
        cart.checkout({ inventoryChecker: checker }),
      ).rejects.toThrow(InventoryError);
      try {
        await cart.checkout({ inventoryChecker: checker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(10);
        expect(err.available).toBe(3);
      }
    });

    it("checks all items and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);
      const checker: InventoryChecker = {
        check: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve({ available: true });
          return Promise.resolve({ available: false, reason: "discontinued" });
        }),
      };
      await expect(
        cart.checkout({ inventoryChecker: checker }),
      ).rejects.toThrow(InventoryError);
    });

    it("skips inventory check when no checker provided", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider for tax calculation", async () => {
      const cart = new Cart();
      cart.add(productA, 1); // subtotal 1000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100); // 10% of 1000
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies async tax on discounted subtotal", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(50),
      });
      cart.add(productA, 1); // subtotal=1000, discount=500, discounted=500
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(50); // 10% of 500
    });

    it("propagates async tax provider error", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service down",
      );
    });

    it("uses sync tax calculator when no async provider given", async () => {
      const cart = new Cart({ region: "US" });
      cart.add(productA, 1);
      const result = await cart.checkout();
      // default NoTaxCalculator → 0
      expect(result.totals.taxCents).toBe(0);
    });
  });

  describe("full pipeline composition", () => {
    it("composes price refresh + discount + async tax + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US-CA",
      });
      cart.add(productA, 2); // original subtotal 2000

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider,
      });

      // subtotal = 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount = 10% of 2400 = 240
      expect(result.totals.discountCents).toBe(240);
      // discounted = 2400 - 240 = 2160
      // tax = floor(2160 * 0.0875) = floor(189) = 189
      expect(result.totals.taxCents).toBe(189);
      // shipping = 500 (flat)
      expect(result.totals.shippingCents).toBe(500);
      // total = 2160 + 189 + 500 = 2849
      expect(result.totals.totalCents).toBe(2849);

      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("returns lines with refreshed prices", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) => {
          return Promise.resolve(id === "a" ? 999 : 1999);
        }),
      };

      const result = await cart.checkout({ priceFetcher: fetcher });
      const prices = result.lines.map((l) => l.product.unitPriceCents);
      expect(prices).toContain(999);
      expect(prices).toContain(1999);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for any positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative percent", () => {
      expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects percent > 100", () => {
      expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
    });

    it("rejects NaN", () => {
      expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
    });

    it("rejects Infinity", () => {
      expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
    });

    it("accepts 0 percent", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
    });

    it("accepts 100 percent", () => {
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 = 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → floor = 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("100% discount equals subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles very large subtotal", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999999999)).toBe(
        Math.floor((999999999 * 15) / 100),
      );
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal is larger", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(10000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(5000);
      expect(policy.computeDiscountCents(3000)).toBe(3000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("zero discount always returns 0", () => {
      const policy = new FixedAmountDiscountPolicy(0);
      expect(policy.computeDiscountCents(10000)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        /at least one policy/,
      );
    });

    it("accepts single policy", () => {
      expect(
        () => new CompositeDiscountPolicy([new NoDiscountPolicy()]),
      ).not.toThrow();
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 1000
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("each child receives original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 5000
          new PercentageDiscountPolicy(50), // 5000
        ],
        "sum",
      );
      // Both get 10000 as input, sum = 10000
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 10000 = 5000, remaining = 5000
          new PercentageDiscountPolicy(50), // 50% of 5000 = 2500, remaining = 2500
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(7500);
    });

    it("order matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // 1000 off 10000, rem=9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900
        ],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, rem=9000
          new FixedAmountDiscountPolicy(1000), // 1000 off 9000
        ],
        "chain",
      );
      expect(composite1.computeDiscountCents(10000)).toBe(1900);
      expect(composite2.computeDiscountCents(10000)).toBe(2000);
    });

    it("caps each step at remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(8000), // takes 8000, remaining = 2000
          new FixedAmountDiscountPolicy(5000), // capped at 2000
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(20)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
