      const calc = new FlatShippingCalculator(500);
      expect(
        calc.computeShippingCents([makeLine("a", 100000, 1)], 100000),
      ).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        /at least one weight bracket/,
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 200 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 200 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for zero-weight cart", () => {
      const lines = [makeLine("a", 100, 2)]; // no weightGrams
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const lines = [makeLine("a", 100, 1, 400)];
      expect(calc.computeShippingCents(lines, 100)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const lines = [makeLine("a", 100, 1, 500)];
      expect(calc.computeShippingCents(lines, 100)).toBe(300);
    });

    it("selects next bracket when weight exceeds previous", () => {
      const lines = [makeLine("a", 100, 1, 501)];
      expect(calc.computeShippingCents(lines, 100)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      const lines = [makeLine("a", 100, 1, 5000)];
      expect(calc.computeShippingCents(lines, 100)).toBe(1200);
    });

    it("uses overflow (last bracket cost) when weight exceeds all brackets", () => {
      const lines = [makeLine("a", 100, 1, 6000)];
      expect(calc.computeShippingCents(lines, 100)).toBe(1200);
    });

    it("uses explicit overflowCostCents when set", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 100, 1, 6000)];
      expect(calcWithOverflow.computeShippingCents(lines, 100)).toBe(2000);
    });

    it("sums weight across multiple lines", () => {
      const lines = [
        makeLine("a", 100, 2, 300), // 600g
        makeLine("b", 200, 1, 200), // 200g
      ];
      // total = 800g → bracket 1000g = 600 cents
      expect(calc.computeShippingCents(lines, 500)).toBe(600);
    });

    it("sorts brackets by upToGrams regardless of input order", () => {
      const unsortedCalc = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      const lines = [makeLine("a", 100, 1, 400)];
      expect(unsortedCalc.computeShippingCents(lines, 100)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product again", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("adds different products separately", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      expect(cart.itemCount).toBe(3);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes a product and returns true", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of an existing product", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 1)).toThrow(
        /not in the cart/,
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);
    });

    it("mutations to snapshot do not affect cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals — pricing pipeline", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2500
      const t = cart.totals();
      expect(t.subtotalCents).toBe(4500);
    });

    it("applies discount policy", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(productA, 1); // subtotal = 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(500);
      expect(discount.computeDiscountCents).toHaveBeenCalledWith(1000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 9999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(productA, 1); // subtotal = 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: () => -100,
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(productA, 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(50),
      };
      const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
      cart.add(productA, 1); // subtotal = 1000, discount = 500, discounted = 500
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(500, "US");
    });

    it("uses configured region for tax", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(productA, 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("computes shipping on lines and discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(799),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(productA, 1); // subtotal=1000, discounted=800
      cart.totals();
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
      const tax: TaxCalculator = { computeTaxCents: () => 80 };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(productA, 1); // subtotal=1000, discount=200, discounted=800
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1000);
      expect(t.discountCents).toBe(200);
      expect(t.taxCents).toBe(80);
      expect(t.shippingCents).toBe(500);
      expect(t.totalCents).toBe(800 + 80 + 500); // 1380
    });

    it("empty cart has all zeros", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = { computeTaxCents: () => -100 };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: () => -50,
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });
});

