      // default NoTaxCalculator → 0
      expect(result.totals.taxCents).toBe(0);
    });
  });

  describe("full pipeline composition", () => {
    it("composes price refresh + discount + async tax + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US-CA",
      });
      cart.add(productA, 2); // original subtotal 2000

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider,
      });

      // subtotal = 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount = 10% of 2400 = 240
      expect(result.totals.discountCents).toBe(240);
      // discounted = 2400 - 240 = 2160
      // tax = floor(2160 * 0.0875) = floor(189) = 189
      expect(result.totals.taxCents).toBe(189);
      // shipping = 500 (flat)
      expect(result.totals.shippingCents).toBe(500);
      // total = 2160 + 189 + 500 = 2849
      expect(result.totals.totalCents).toBe(2849);

      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("returns lines with refreshed prices", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) => {
          return Promise.resolve(id === "a" ? 999 : 1999);
        }),
      };

      const result = await cart.checkout({ priceFetcher: fetcher });
      const prices = result.lines.map((l) => l.product.unitPriceCents);
      expect(prices).toContain(999);
      expect(prices).toContain(1999);
    });
  });
});

